import React, { useEffect, useState } from "react";
import UsageBarChart from "./components/UsageBarChart";
import UsagePieChart from "./components/UsagePieChart";
import ActivityList from "./components/ActivityList";


export default function App() {
  const [summary, setSummary] = useState([]);
  const [sessions, setSessions] = useState([]);

  useEffect(() => {
    fetch("http://localhost:5000/api/analytics/summary")
      .then(res => res.json())
      .then(setSummary);

    fetch("http://localhost:5000/api/analytics")
      .then(res => res.json())
      .then(setSessions);
  }, []);

  /* ---------------- KPI CALCULATIONS ---------------- */

  const totalTime = summary.reduce(
    (acc, item) => acc + item.totalTime,
    0
  );

  const totalSites = summary.length;

  const mostUsedSite =
    summary.length > 0
      ? summary.reduce((max, item) =>
          item.totalTime > max.totalTime ? item : max
        ).url
      : "N/A";

  const totalSessions = sessions.length;

  /* -------------------------------------------------- */

  return (
    <div className="container">
      <h1>📊 Website Activity Dashboard</h1>

      {/* ================= KPI CARDS ================= */}
      <div className="kpi-grid">
        <div className="kpi-card">
          <h3>Total Time Spent</h3>
          <p>{Math.round(totalTime / 60)} mins</p>
        </div>

        <div className="kpi-card">
          <h3>Websites Visited</h3>
          <p>{totalSites}</p>
        </div>

        <div className="kpi-card">
          <h3>Most Used Site</h3>
          <p>{mostUsedSite}</p>
        </div>

        <div className="kpi-card">
          <h3>Total Sessions</h3>
          <p>{totalSessions}</p>
        </div>
      </div>
      {/* ============================================== */}

      <div className="card">
        <h2>Daily Usage (Bar)</h2>
        <UsageBarChart data={summary} />
      </div>

      <div className="card">
        <h2>Usage Share (Pie)</h2>
        <UsagePieChart data={summary} />
      </div>

      <div className="card">
        <h2>📱 App Activity</h2>
        <ActivityList sessions={sessions} />
      </div>
    </div>
  );
}
